    acknowledgeProblems: {
        parameters: {
            query?: never;
            header?: {
                /**
                 * @description Must be `1` on sign-in, sign-out, the request for an account and every `POST`, `PUT`, `PATCH` or `DELETE` that
                 *     authenticates with the session cookie. A page on another site cannot add a custom header
                 *     without a CORS preflight, which the BFF answers only for `WEB_ORIGIN`. Not needed with a
                 *     Bearer header, except on sign-in, sign-out and the request for an account.
                 */
                "X-HCML-CSRF"?: components["parameters"]["CsrfHeader"];
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description One id or an array. Non-string members are dropped silently. */
                    eventids: string | string[];
                    message?: string;
                    /** @default false */
                    close?: boolean;
                    /** @default true */
                    acknowledge?: boolean;
                };
            };
        };
        responses: {
            /** @description Written. `action` is the Zabbix bitmask, close 1, acknowledge 2, message 4. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @constant */
                        ok: true;
                        eventids: string[];
                        action: number;
                    };
                };
            };
            /**
             * @description No usable event ids, more than 50 of them, a non-numeric id, a body or field of the wrong type, or nothing to do:
             *     `acknowledge: false` with no `close` and no `message`.
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /**
             * @description `forbidden`, the role is below operator, or `csrf`, a cookie request without
             *     `X-HCML-CSRF: 1` or from another site (`CsrfRefused`).
             */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            413: components["responses"]["PayloadTooLarge"];
            /**
             * @description `rate_limited`. This person has acknowledged or closed more than `ACTION_EVENTS_PER_MINUTE` events in the last minute (200 by default, 50 at the least),
             *     counted by event id and only for a request that would be written; `Retry-After` says how long to wait. The portal-wide limit (`RateLimited`) answers in the same shape.
             */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description `zabbix_error`. When Zabbix answered with an error, the message says that Zabbix refused the change and may already have
             *     closed the problem, or the account may not be allowed to change it; Zabbix's own words go to the log. When the portal
             *     cannot tell what Zabbix did with the request (an error page, a body that is not JSON-RPC, or a connection that failed
             *     when the request may have left), it says the change may or may not have been made. When Zabbix could not be reached
             *     at all, it says the data source is not answering.
             */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /**
             * @description `zabbix_write_disabled`, `ZABBIX_WRITE_TOKEN` is not set, or sign-in is off and `ALLOW_WRITE_WITHOUT_AUTH` is not true.
             *     Or `zabbix_timeout`: Zabbix did not answer in time, and the message says that the change may or may not have been made.
             *     Or `zabbix_auth`, Zabbix rejected the write token.
             */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
